-- Embers of the Last Empire (38 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('e2e3cb86-6cd1-508d-acdf-397d3610522c', '555aeb0c-a518-528a-ae47-6ae57437c77d', 'Embers of the Last Empire', 'embers-of-the-last-empire', 'The Empire of Calix burned in a single night, and its youngest princess, Aurelie, survived by hiding in a bread oven. Ten years later she is a scribe in the court of the general who lit the fires. He is a good ruler. That is the problem. When the old Empire''s loyalists come for her, Aurelie must decide whether a crown is worth another war.', 'ongoing', 'teen', now() - interval '135.70 days')
on conflict (id) do nothing;
insert into public.story_genres (story_id, genre_id) select 'e2e3cb86-6cd1-508d-acdf-397d3610522c', id from public.genres where slug in ('fantasy', 'drama') on conflict do nothing;
