insert into public.story_tags (story_id, tag_id) select 'e2e3cb86-6cd1-508d-acdf-397d3610522c', id from public.tags where slug in ('war', 'politics', 'morally-grey') on conflict do nothing;
insert into public.chapters (id, story_id, number, title, body, status, published_at, created_at) values
  ('3c0253c3-4ee6-584a-a0e7-41bcbe389575', 'e2e3cb86-6cd1-508d-acdf-397d3610522c', 1, 'The Bread Oven', 'Aurelie remembered the bread oven better than she remembered her mother''s face. It was warm, and it smelled of yeast, and the baker''s boy who pushed her into it had said only, ''Don''t make a sound, highness,'' before he closed the iron door.

She did not make a sound for nine hours. She listened to the palace burn. When the door finally opened, the boy was gone, and a stranger with ash on her apron lifted her out, looked at her fine nightdress, and tore it to rags without a word.

Ten years later, Aurelie kept the general''s records in a scribe''s grey robe and never, ever ate warm bread.

The council chamber was cold even in summer, its high windows letting in light but never warmth.

"I burned a palace so a city could eat." General Varro paused. "I would do it again, and I will never forgive myself."

On her desk in the morning lay a gold sun pressed into wax, the old Empire''s seal.', 'published', now() - interval '134.703 days', now() - interval '134.703 days'),
  ('8551b446-f713-504a-a376-cf3bbb8dfd2f', 'e2e3cb86-6cd1-508d-acdf-397d3610522c', 2, 'The Good Ruler', 'In which Aurelie records Varro''s council and is forced to admit his Republic feeds more people than the Empire ever did.

In the scriptorium, the scratch of a dozen pens filled the silence, recording the decisions of a government that worked.

Aurelie had learned that history was a draft. Someone always got to make corrections.

"I burned a palace so a city could eat." General Varro paused. "I would do it again, and I will never forgive myself."

Smoke from the bakeries drifted over the rebuilt city every morning, and Aurelie walked the long way to avoid it.

Every law Varro passed was fair. Every fair law made her hatred harder to hold, like a coal that would not stay lit.

"The Empire isn''t dead, highness. It''s waiting for you to stand up," Lucan said.

On her desk in the morning lay a gold sun pressed into wax, the old Empire''s seal.', 'published', now() - interval '131.064 days', now() - interval '131.064 days'),
  ('86e0096c-072a-55fd-a459-a20b84dbcc2f', 'e2e3cb86-6cd1-508d-acdf-397d3610522c', 3, 'Sabine', 'In which Aurelie''s sharp-tongued fellow scribe Sabine notices that Aurelie writes the old imperial script without thinking.

The council chamber was cold even in summer, its high windows letting in light but never warmth.

She wondered sometimes what her father would have done with ten years. She suspected it would have been worse.

General Varro said, "A good scribe writes what was said. A great one writes what was meant. Which are you?"

Banners of the new Republic hung over the square, red and plain, nothing like the Empire''s old gold suns.

Aurelie had learned that history was a draft. Someone always got to make corrections.

Lucan''s message was three words long, and one of them was her real name.', 'published', now() - interval '127.601 days', now() - interval '127.601 days'),
  ('335e011f-0bb3-5dce-a79d-613d20c433e1', 'e2e3cb86-6cd1-508d-acdf-397d3610522c', 4, 'The Gold Sun', 'In which a wax seal of the old Empire''s gold sun appears on Aurelie''s desk. Someone knows who she is.

In the scriptorium, the scratch of a dozen pens filled the silence, recording the decisions of a government that worked.

Aurelie had built her life on staying invisible. She had become very good at it, and very tired.

"You keep his records so well. One might think you admire him," Sabine said.

Smoke from the bakeries drifted over the rebuilt city every morning, and Aurelie walked the long way to avoid it.

She wondered sometimes what her father would have done with ten years. She suspected it would have been worse.

"A good scribe writes what was said." General Varro paused. "A great one writes what was meant. Which are you?"

The council voted that afternoon, and the scribe''s pen in her hand trembled for the first time.', 'published', now() - interval '124.205 days', now() - interval '124.205 days'),
  ('58d72155-52a3-59f7-a35e-a883b4ead885', 'e2e3cb86-6cd1-508d-acdf-397d3610522c', 5, 'Lucan', 'In which Lucan, the baker''s boy who once hid her in the oven, finds her. He now leads the Empire''s loyalists in the hills.

The council chamber was cold even in summer, its high windows letting in light but never warmth.

The people in the market did not miss the Empire. That was the truth she wrote around most carefully.

"Crowns are just very expensive ways of getting people killed," Sabine said quietly.

Banners of the new Republic hung over the square, red and plain, nothing like the Empire''s old gold suns.

Aurelie had built her life on staying invisible. She had become very good at it, and very tired.

"You keep his records so well. One might think you admire him," Sabine said.

The general looked up from his papers and asked her, quite casually, whether she had ever been afraid of ovens.', 'published', now() - interval '120.774 days', now() - interval '120.774 days'),
