insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('49006ee7-0db1-5693-a80a-aad669125b6b', '271f978e-4288-5bd3-a8dc-7035441b8054', 'Deep Shift', 'deep-shift', 'Benthos Station sits four thousand metres down on the floor of the Hadal Trench, mining nodules no one on the surface can reach. When the relief sub fails to arrive and the station''s lights start dimming in a pattern, eight crew members discover they are not the deepest thing in the trench. Something down there has learned their shift schedule.', 'completed', 'mature', now() - interval '145.93 days')
