insert into public.story_tags (story_id, tag_id) select '49006ee7-0db1-5693-a80a-aad669125b6b', id from public.tags where slug in ('underwater', 'survival', 'claustrophobic') on conflict do nothing;
insert into public.chapters (id, story_id, number, title, body, status, published_at, created_at) values
  ('1d81d7d2-a534-5af0-a209-791d2b219a57', '49006ee7-0db1-5693-a80a-aad669125b6b', 1, 'Relief', 'Four thousand metres of water presses on Benthos Station at four hundred times the weight of air. Rhea Castell knew the number by heart. Everyone on the deep shift did. You said it to yourself when the hull creaked at night, like a prayer, or a dare.

The relief sub was due at 06:00. Rhea was awake at 05:30, packed, sitting on her bunk with her bag on her knees like a child waiting for a school trip.

At 06:00 the docking light stayed red. At 06:30 it was still red. At 07:00 every light on the station dimmed at once, held for three seconds, and came back.

On the third dimming, she counted. Three seconds. Then two. Then three again.

The station''s hull groaned under the weight of the trench, a long low sound like a ship settling at anchor.

"Down here, panic uses oxygen." Okonkwo paused. "Be scared quietly."

The lights dimmed again: three seconds, two seconds, three seconds. Then, for the first time, four.', 'published', now() - interval '144.934 days', now() - interval '144.934 days'),
  ('22c41f9f-24aa-56cf-ab6a-8d34371a6b53', '49006ee7-0db1-5693-a80a-aad669125b6b', 2, 'Three, Two, Three', 'In which engineer Rhea Castell notices the dimming follows a rhythm. Station chief Okonkwo blames a faulty power coupling.

The corridors were narrow and lit with blue strips, and every hatch had to be wrestled shut with both hands.

Down here, Rhea thought, the dark wasn''t an absence. It was a presence that hadn''t introduced itself yet.

Okonkwo said, "Down here, panic uses oxygen. Be scared quietly."

Outside the viewport there was only black, and occasionally a drifting speck of something pale caught in the floodlights.

Every hatch she sealed felt like a decision she couldn''t take back.

"Life adapts. Everything we know says this trench should be empty. Everything we know is from the surface," Dr Lindqvist said.

The relief sub''s signal finally came through. It was coming from beneath the station.', 'published', now() - interval '140.045 days', now() - interval '140.045 days'),
  ('a242c737-c298-5c00-a268-cb95e7dcdca1', '49006ee7-0db1-5693-a80a-aad669125b6b', 3, 'No Signal', 'In which the comms buoy has gone silent. The crew is cut off from the surface with three weeks of supplies.

The station''s hull groaned under the weight of the trench, a long low sound like a ship settling at anchor.

The surface felt like a story someone had told her once, too bright to be real.

"Count the hatches." Okonkwo paused. "If you lose count down here, you lose everything."

Somewhere below the station, in the dark, something knocked once against the hull, slow and deliberate.

Down here, Rhea thought, the dark wasn''t an absence. It was a presence that hadn''t introduced itself yet.

"Down here, panic uses oxygen." Okonkwo paused. "Be scared quietly."

Something knocked on the hull outside her bunk, three times, and then on the hatch inside.', 'published', now() - interval '135.368 days', now() - interval '135.368 days'),
  ('f5a29956-26d4-5486-a6cc-930ec19460ec', '49006ee7-0db1-5693-a80a-aad669125b6b', 4, 'The Drones', 'In which the mining drones return early with strange scratches on their hulls, as if something tried to open them.

The corridors were narrow and lit with blue strips, and every hatch had to be wrestled shut with both hands.

Rhea had always liked the deep for its silence. Now she listened to the silence the way you listen to someone breathing in the next room.

"Four thousand metres, Rhea." Mags paused. "Nothing lives this deep that wants to meet us."

Outside the viewport there was only black, and occasionally a drifting speck of something pale caught in the floodlights.

The surface felt like a story someone had told her once, too bright to be real.

The lights dimmed again: three seconds, two seconds, three seconds. Then, for the first time, four.', 'published', now() - interval '130.469 days', now() - interval '130.469 days'),
  ('d95eb377-c467-56b8-acb2-68827037525b', '49006ee7-0db1-5693-a80a-aad669125b6b', 5, 'Dr Lindqvist', 'In which biologist Dr Lindqvist studies the scratch marks and finds traces of organic material no database recognises.

The station''s hull groaned under the weight of the trench, a long low sound like a ship settling at anchor.

She found herself counting in threes now, without meaning to.

"It''s following the shift rota. It knows when we sleep," Mags said.

Somewhere below the station, in the dark, something knocked once against the hull, slow and deliberate.

Rhea had always liked the deep for its silence. Now she listened to the silence the way you listen to someone breathing in the next room.

Mags said, "Four thousand metres, Rhea. Nothing lives this deep that wants to meet us."

Something knocked on the hull outside her bunk, three times, and then on the hatch inside.', 'published', now() - interval '125.644 days', now() - interval '125.644 days'),
  ('c769184f-e6e0-5e72-a4c6-a223b5f884ff', '49006ee7-0db1-5693-a80a-aad669125b6b', 6, 'Night Shift', 'In which on night shift, Rhea sees a pale shape drift past the viewport, too large and too deliberate to be debris.

The corridors were narrow and lit with blue strips, and every hatch had to be wrestled shut with both hands.

Every hatch she sealed felt like a decision she couldn''t take back.

"Life adapts." Dr Lindqvist paused. "Everything we know says this trench should be empty. Everything we know is from the surface."

Outside the viewport there was only black, and occasionally a drifting speck of something pale caught in the floodlights.

She found herself counting in threes now, without meaning to.

Mags said, "It''s following the shift rota. It knows when we sleep."

