insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('4dd7bf9e-6351-5dfc-a998-683a27007786', 'ce2e4569-4ae5-58d7-ad3a-bdd2e5ea96d6', 'Coffee at the End of the Street', 'coffee-at-the-end-of-the-street', 'Jun Park opens a tiny coffee shop at the dead end of Alder Street, where nobody walks unless they''re lost. The only regular is a grumpy bookbinder who complains about the music and comes back every single day. They were each other''s first love at seventeen. Neither of them is ready to mention it.', 'completed', 'everyone', now() - interval '85.80 days')
