insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('7a307cbd-2824-5884-aaf7-5b89bb6edbb7', 'b66999fb-77b7-51da-a95d-f64a0003e286', 'The Thousand-Year Apprentice', 'the-thousand-year-apprentice', 'Song Ping has been an apprentice of the Cloudy Peak Sect for a thousand years. Not because he is weak; he is, frankly, terrifying. It is because his master told him to wait at the gate until he returned, and then forgot. When a lost young disciple stumbles into the long-abandoned sect, Song Ping finally has someone to teach, and absolutely no idea how normal cultivation works anymore.', 'ongoing', 'everyone', now() - interval '112.80 days')
