insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('49af270f-d457-5324-a474-492be457e16f', 'b2879b31-dcb4-5578-a48f-435b7bb207d2', 'Glass Hearts', 'glass-hearts', 'St Aldric''s Academy keeps a glass case in its great hall with one heart-shaped crystal for each student who has died during term. There are nineteen. Scholarship student Zara Okafor arrives the term after the nineteenth is added, and finds a note under her mattress from the girl who slept in her bed before her: ''They will tell you it was an accident. Count the hearts.''', 'ongoing', 'teen', now() - interval '70.65 days')
