insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('8d17853b-57c5-5d68-a337-45a575609c90', 'db1a6229-ecff-506c-a86a-26dba1aef994', 'System Error: Tower Climber', 'system-error-tower-climber', 'The Tower appeared over Lagos with a hundred floors and a promise: whoever reaches the top gets one wish. Ten years later, the best guilds are stuck on floor sixty. Courier Dayo Adebayo isn''t trying to climb anything; he''s delivering lunch to floor three when the System glitches and assigns him a class that doesn''t exist: [Error].', 'ongoing', 'teen', now() - interval '100.74 days')
