values ('af2bf517-2e7b-545b-a05f-12ccab8d958d', 'b2879b31-dcb4-5578-a48f-435b7bb207d2', 'The Weaver''s Daughter', 'the-weavers-daughter', 'In the city of Ilé-Òrun, the master weavers spin cloth that remembers: a wedding cloth holds the vows, a funeral cloth holds the mourning. Adaeze''s mother was the greatest weaver of her generation until the night her loom wove a prophecy of the king''s death, and she vanished. Now Adaeze is sixteen, untrained, and the only one who can read the cloth her mother left behind.', 'ongoing', 'everyone', now() - interval '90.96 days')
on conflict (id) do nothing;
insert into public.story_genres (story_id, genre_id) select 'af2bf517-2e7b-545b-a05f-12ccab8d958d', id from public.genres where slug in ('fantasy') on conflict do nothing;
insert into public.tags (slug, name) values ('west-african-inspired', 'West African Inspired'), ('magic', 'Magic'), ('coming-of-age', 'Coming of Age') on conflict (slug) do nothing;
insert into public.story_tags (story_id, tag_id) select 'af2bf517-2e7b-545b-a05f-12ccab8d958d', id from public.tags where slug in ('west-african-inspired', 'magic', 'coming-of-age') on conflict do nothing;
insert into public.chapters (id, story_id, number, title, body, status, published_at, created_at) values
  ('eb596bf2-5e1a-5abd-abb5-26e3b25f20fd', 'af2bf517-2e7b-545b-a05f-12ccab8d958d', 1, 'The Whispering Cloth', 'Adaeze could hear cloth. She had never told anyone. When she was small, she thought everyone could; she thought the whole market heard the indigo wraps humming lullabies and the kente arguing proudly about whose ancestors had been bravest.

Then her mother vanished, and the weavers'' guild sealed the house, and Adaeze was sent to live with an aunt who sold onions and did not hear anything at all except the price of onions.

On the morning of her sixteenth birthday, a parcel arrived with no sender. Inside was a strip of cloth in her mother''s colours, woven in her mother''s hand. It was whispering her name.

The great market of Ilé-Òrun spread beneath the palace walls, a sea of awnings and voices and dyed cloth drying in the sun.

"Onions don''t keep secrets, child." Mama Nkechi paused. "That''s why I like them. Your mother''s cloth is a different matter."

That night, the strip of cloth wove a new line into itself while she slept.', 'published', now() - interval '89.964 days', now() - interval '89.964 days'),
  ('c2571935-4704-5978-a64c-1e72f738cc6a', 'af2bf517-2e7b-545b-a05f-12ccab8d958d', 2, 'Mama Nkechi', 'In which Adaeze''s aunt Mama Nkechi, an onion seller, admits Adaeze''s mother sent the cloth and begs her not to follow it.

Rain came hard and sudden off the hills, and every awning in the market became a small, loud drum of its own.

Adaeze was sixteen and untrained and probably out of her depth. She found she did not much care.

Mama Nkechi said, "Onions don''t keep secrets, child. That''s why I like them. Your mother''s cloth is a different matter."

Indigo vats bubbled in the dyers'' quarter, and the air there smelled of ash, leaves and something deep and earthy.

Her mother''s colours were in everything now: the market, the sky, her dreams. She had stopped trying to ignore them.

The prince''s cloak, she noticed as he left, had been woven by her mother, and it was frightened.', 'published', now() - interval '86.779 days', now() - interval '86.779 days'),
  ('81fb4f84-f61c-5595-aa6c-ca2c3050b470', 'af2bf517-2e7b-545b-a05f-12ccab8d958d', 3, 'The Sealed House', 'In which Adaeze sneaks into her mother''s sealed house and finds the old loom. It begins to weave by itself when she touches it.

The great market of Ilé-Òrun spread beneath the palace walls, a sea of awnings and voices and dyed cloth drying in the sun.

The guild called her mother a traitor. The cloth called her mother something else, and Adaeze was learning whom to believe.

Mama Nkechi said, "If you go into that guild hall, go with your mouth closed and your ears open."

In the weavers'' quarter, the clack of looms ran from dawn to dusk like a vast wooden heartbeat.

Adaeze was sixteen and untrained and probably out of her depth. She found she did not much care.

The palace drums beat at midnight, which they only did when the king was ill.', 'published', now() - interval '84.024 days', now() - interval '84.024 days'),
  ('399e2844-3c56-556f-af4b-3dc70d22b2af', 'af2bf517-2e7b-545b-a05f-12ccab8d958d', 4, 'Iya Ronke', 'In which The ancient weaver Iya Ronke, her mother''s old teacher, catches Adaeze in the house and offers to teach her, in secret.

Rain came hard and sudden off the hills, and every awning in the market became a small, loud drum of its own.

Adaeze had spent years pretending not to hear the cloth. Listening again felt like remembering how to breathe.

"A weaver doesn''t make the pattern. She listens for it. Your mother listened too well," Iya Ronke said.

Indigo vats bubbled in the dyers'' quarter, and the air there smelled of ash, leaves and something deep and earthy.

The guild called her mother a traitor. The cloth called her mother something else, and Adaeze was learning whom to believe.

Mama Nkechi said, "If you go into that guild hall, go with your mouth closed and your ears open."

That night, the strip of cloth wove a new line into itself while she slept.', 'published', now() - interval '81.116 days', now() - interval '81.116 days'),
  ('96545934-c73e-50eb-a356-47571b4e4990', 'af2bf517-2e7b-545b-a05f-12ccab8d958d', 5, 'Listening', 'In which Iya Ronke teaches Adaeze that weaving is listening. Adaeze''s first cloth hums the gossip of the whole street.

The great market of Ilé-Òrun spread beneath the palace walls, a sea of awnings and voices and dyed cloth drying in the sun.

Every thread she pulled seemed to be tied to something larger, something that went all the way to the palace.

"Every thread remembers. The trick is asking it the right question," Iya Ronke said.

In the weavers'' quarter, the clack of looms ran from dawn to dusk like a vast wooden heartbeat.

Adaeze had spent years pretending not to hear the cloth. Listening again felt like remembering how to breathe.

The palace drums beat at midnight, which they only did when the king was ill.', 'published', now() - interval '77.984 days', now() - interval '77.984 days'),
  ('c8c373c1-a40a-570e-af3e-148d6afd9306', 'af2bf517-2e7b-545b-a05f-12ccab8d958d', 6, 'The Prophecy Cloth', 'In which Iya Ronke tells Adaeze about the night her mother wove a cloth foretelling the king''s death. The guild declared it treason.

Rain came hard and sudden off the hills, and every awning in the market became a small, loud drum of its own.

Her mother''s colours were in everything now: the market, the sky, her dreams. She had stopped trying to ignore them.

"Everyone at court says your mother was a traitor. I''ve read her cloth. Traitors don''t weave like that," Prince Olu said.

Indigo vats bubbled in the dyers'' quarter, and the air there smelled of ash, leaves and something deep and earthy.

Every thread she pulled seemed to be tied to something larger, something that went all the way to the palace.

Iya Ronke said, "Every thread remembers. The trick is asking it the right question."

At the market gate, a guild enforcer was asking the onion sellers about a girl who could hear cloth.', 'published', now() - interval '75.201 days', now() - interval '75.201 days'),
