-- Sixteen Rooms (20 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('cfefaaff-f064-5e08-a2c1-20ae2192cb6d', '271f978e-4288-5bd3-a8dc-7035441b8054', 'Sixteen Rooms', 'sixteen-rooms', 'Sixteen strangers wake in sixteen identical rooms in a house with no windows. Each room has a door, a desk, and a card with a single sentence about a secret only that person knows. Every hour, one door unlocks. Paramedic Iris Nakamura has to work out the house''s rules before the house works out hers.', 'completed', 'mature', now() - interval '155.90 days')
on conflict (id) do nothing;
