insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('6970c36d-a4d0-5de4-ab4d-beef4b5e228c', '7871dcac-1355-5d44-ae1b-0dbae85390ce', 'My Rival Is the Demon King''s Tutor', 'my-rival-is-the-demon-kings-tutor', 'Hikari Mizuno, top student of her Tokyo high school, gets summoned to another world as a hero and spends a year perfecting her sword arm. Then she''s sent back, to find her school rival Sora Amano has also been summoned somewhere: as the Demon King''s maths tutor. Now they''re both back in class, both hiding a second life, and both very, very competitive.', 'ongoing', 'everyone', now() - interval '2.98 days')
