-- Shieldmaiden's Oath (30 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('e115cf2b-5a7e-5b67-a2a7-cfa3c6c07cc5', 'dab4cd47-fa16-5b6d-aa59-526c7ac4c165', 'Shieldmaiden''s Oath', 'shieldmaidens-oath', 'Norway, 993. When raiders burn the farmstead of Hrafnsvík, fourteen-year-old Sigrun swears an oath over her father''s grave to find the man with the silver-ringed axe. Oaths, her grandmother warns her, are heavier than iron. Seven winters later, Sigrun stands on the deck of a jarl''s longship, sworn to a man she does not trust, sailing toward the one she has hunted all her life.', 'ongoing', 'teen', now() - interval '115.74 days')
