insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('e1cd2a03-2c69-5f07-a242-abe5f81563d1', '53c8c6e4-5f89-5bcb-a629-282e97ba3e5f', 'Stardust Couriers', 'stardust-couriers', 'The Lucky Kettle is the worst-rated courier ship in the Outer Ring: late, dented, and crewed by a pilot who talks to the engine, a mechanic who is technically a sentient fungus, and a captain who owes money to everyone. When they accept a ''no questions asked'' delivery that turns out to be a runaway princess, they suddenly have a lot of questions.', 'ongoing', 'everyone', now() - interval '58.91 days')
on conflict (id) do nothing;
