-- The Clockwork Heir (24 chapters)
insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('18d6bfd3-1cca-557d-aa3e-cb4fe15ec5eb', '555aeb0c-a518-528a-ae47-6ae57437c77d', 'The Clockwork Heir', 'the-clockwork-heir', 'When the eccentric inventor Lord Ashgrove dies, his will leaves his vast clockwork estate to whichever of his seven relatives can open the Heart, a brass safe at the centre of the house that answers only to its maker. His housekeeper''s daughter, Wren, is not an heir. But she grew up inside the walls of Ashgrove Hall, and she is the only one who knows the house is still running on its own.', 'completed', 'everyone', now() - interval '160.98 days')
on conflict (id) do nothing;
