insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('054b855b-86c2-50d2-a240-01ecd72ce88f', 'dab4cd47-fa16-5b6d-aa59-526c7ac4c165', 'Where the River Bends', 'where-the-river-bends', 'Every summer for twenty years, the Okafor and Lindgren families shared a farm on the bend of the River Eld, until the summer of the flood, when everything was lost and nobody spoke again. Now Chioma Okafor has inherited her half of the farm, and the other half belongs to Erik Lindgren, the boy she once promised to marry under the willow tree.', 'completed', 'everyone', now() - interval '95.85 days')
