insert into public.stories (id, author_id, title, slug, synopsis, status, rating, created_at)
values ('29d31a6b-dc05-58af-a39a-133d2a95b699', '271f978e-4288-5bd3-a8dc-7035441b8054', 'Bones of the Old Gods', 'bones-of-the-old-gods', 'The gods died three hundred years ago, and the kingdoms built their cities on the bones. Ossuary marrow-miners like Kael Vorne dig god-bone from the vast skeletons for the magic it holds. Then a fresh vein is opened beneath the city of Sorrow''s Reach, and the bone in it is warm, and something deep inside the dead god begins, slowly, to dream again.', 'ongoing', 'mature', now() - interval '65.66 days')
